SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for feature_document
-- ----------------------------
DROP TABLE IF EXISTS `feature_document`;
CREATE TABLE `feature_document`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `feature_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '功能名称',
  `english_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '英文名',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编制人',
  `version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '功能版本',
  `publish_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发行日期',
  `company` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属公司',
  `feature_intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '功能简介 JSON',
  `feature_details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '功能描述 JSON数组',
  `operation_guide` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作指南 JSON',
  `faq` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '常见问题 JSON',
  `video_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关联视频URL列表 JSON',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0-未删除 1-已删除',
  `vectorized` tinyint NOT NULL DEFAULT 0 COMMENT '是否已向量化 0-未向量化 1-已向量化',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '功能文档表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of feature_document
-- ----------------------------
INSERT INTO `feature_document` VALUES (1, '赋注解属性工具', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「赋注解属性工具」\\n可用于UG建模档分析预览零件注解以及修改注解\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\"]}', '[{\"title\":\"赋注解属性工具\",\"description\":\"1.选择打开配置表\\n2.选择对象\\n3.选择沉头孔注解为做深或掏留\\n   选择大板不注解槽或注解/不注解所有槽\\n   按需勾选英制牙、英文注解\\n   设置注解图元字体大小、注解颜色\\n4.操作\\n  ①、自动分析注解：导图的前置工作条件，必须分析注解后导图才有注解\\n  ②、删除属性：分析后的注解属性删除\\n  ③、展示图元：3D工件上展示图元\\n  ④、手动添加注解：选择一个或多个孔给予手动注解\\n  ⑤、图层+编号：点开可以选择查看工件注解\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c1b8b947289c437481657442759b25bc.png\"]}]', '{\"description\":\"步骤一:选择需要分析或检查注解的对象\\n步骤二:选择注解要求，自动分析注解\\n步骤三:选择一个面，设置好图元标记和注解信息，添加\\n步骤四:选择要预览注解的工件，图元展示\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39491a55aa614fb9a921bf2ce9133a87.png\"]}', '{\"description\":\"这个×不是报错。确定后要再次打开功能\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\"]}', '[]', 0, 1, '2026-02-28 13:27:25', '2026-03-17 11:08:47');
INSERT INTO `feature_document` VALUES (2, '赋属性工具', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「赋属性工具」\\n可用于生成建模档实体的零件编号、长宽高、材质、热处理、重量、页码属性，为出图的前置条件\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\"]}', '[{\"title\":\"赋属性工具\",\"description\":\"1.写入属性：\\n  写入编号、长宽高、材质、热处理、页码、出图坐标、原点方向等属性\\n2.选择零件\\n  可框选工件或按配置表全选工件\\n3.设置排序编号定义\\n  按图层X+方向排序，也可选按手选顺序编号\\n4.上下模视图方向\\n  选择上模俯/仰视图，下模俯/仰视图\\n5.坐标方向和零件规格\\n  坐标可选按绝对坐标，规格保留工件小数或自动取整\\n6.原点规则\\n  按颜色标记识别原点，首先可设置长于400识别为大板，\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dcdf13d47f634ec0b3385d02a3d4c7cc.png\"]},{\"title\":\"删除属性\",\"description\":\"删除属性：此功能用于删除属性后、重新排序写属性\\n删所有属性，包括编号、长宽高、材质、热处理、页码、出图坐标、原点方向全部删除，注意点删除属性后，要确定生效。 \",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/94e700c0dc324b1cb22866346e63b6d8.png\"]},{\"title\":\"编辑原点\",\"description\":\"编辑原点：此功能用于检查、修改批量/单个工件原点\\n编辑原点：先勾选检查原点，把所有坯料框显示。再选择单个或多个工件修改原点位置，应用更新，确定  \",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\"]},{\"title\":\"添加余量\",\"description\":\"添加余量：此功能用于手动添加工件坯料余量\\n添加余量：勾选检查余量 ，选择工件，自定义余量，注意应用更新再确定。还可勾选生成坯料盒子和勾选记录添加余量\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/591de5feab4740e0aa379eade7d0f573.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/83b338ef3af24aeeb828e787632ff43d.png\"]}]', '{\"description\":\"步骤一:选择写入属性以及客户标准\\n     注意用户标准选择\\n步骤二:选择零件\\n    选择扫描则自动寻找已排序工件\\n步骤三:零件编码排序\\n    检查客户标准\\n步骤四:主视图方向\\n    按需选取俯视图或仰视图\\n步骤五:原点方向规则，默认以长直边短直边为零边，长度默认400为大板分界，亦可自定义\\n  勾选规则1 则指定所选颜色为零边，3D要对应涂色\\n  勾选规则2则自定义长短边比例，如长宽比10:1为长条形工件，原点位 置可设置是四面分中或左下角\\n详细操作内容请看右侧视频\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\"]}', '{\"description\":\"\",\"images\":[]}', NULL, 0, 1, '2026-02-28 13:32:31', '2026-02-28 14:42:09');
INSERT INTO `feature_document` VALUES (3, '建模出图工具', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「建模出图工具」\\n可用于建模档3D导出2D图\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\"]}', '[{\"title\":\"建模出图工具\",\"description\":\"1.可选择并打开对应的配置表\\n2.填写模具编号（必填）\\n3.选择常规出图零件/轻量化出图零件\\n4.选择第一视角/第三视角\\n5.选择要投影的视图，选择球标图、线割涂色、研磨符号\\n（默认选择出主视图 右视图 前视图、要线割的线转2D图默认涂红色186）\\n6.设置球标大小，选择是否要加工说明（打开基本属性表可修改加工说明（图附1））、选择是否英文注解、选择是否英制牙、选择做深/掏留、选择槽注解\\n7.球标大小 附加信息\\n  附加信息在打开配置表的基本属性工作表内，可修改\\n6.图框公共信息\\n  模具名称和产品厚度等信息在基本属性也可配\\n7.填写图纸路径（ 默认在图档当前文件夹创建DWG文件夹）\\n8.填写公共信息（同一套模具，填写一次后会带记忆，下次打开会保留上次使用的信息）\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/a034aebacbe64c33b87503e9ae189b31.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d0972d1d8a4c40d99415d1b0af32bedb.png\"]}]', '{\"description\":\"步骤一:填写模具编号\\n步骤二:选择要出图的零件（按需选择常规或轻量化视图）\\n步骤三:选择第三或第一视角\\n步骤四:选择视图，按需勾选球标图、线割涂色、研磨符号\\n步骤五:设置球标大小，按需勾选加工说明、英文注解、英制牙，选择做深/掏留，选择槽注解，填写图纸路径\\n步骤六:填写对应的信息后确定\\n步骤八:待出图完毕后打开图纸路径查看图纸\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\"]}', '{\"description\":\"\",\"images\":[]}', NULL, 0, 1, '2026-02-28 13:34:23', '2026-02-28 14:50:57');
INSERT INTO `feature_document` VALUES (4, 'BOM工具', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「BOM表工具」\\n可用于导出材料清单、标准件清单、成本预算清单\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\"]}', '[{\"title\":\"BOM工具\",\"description\":\"1.客户图层编码、BOM模板\\n  客户自己的图层标准、BOM模板标准，可查看配置表\\n2.选择BOM表类型\\n  ①、材料清单、标准件清单和成本预算单\\n  ②、已备料不出料单（备料后的单个零件图不导BOM）\\n  ③、分页按类型导出BOM表（可选按名称/材质/品牌分类，每页行数20-40之间）\\n3.扫描BOM表、导出EXCEL表\\n  ①、扫描整个图档 有属性的工件\\n  ②、选择实体生成\\n  ③、导出EXCEL表\\n  ④、导出EXCEL表后可以转成TXT文本\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]}]', '{\"description\":\"步骤一:填写并检查客户信息、模号、产品编号\\n步骤二:选择BOM表类型\\n步骤三:按需勾选已备料不出料单，是否分页，设置分页类型和行数\\n步骤四:扫描所有实体出BOM表或者选择实体生成\\n步骤五:点击导出EXCEL。导出EXCEL后如有需要可以点击EXCEL转TXT文本    \\n材料清单、标准件清单、成本预算单操作方式一样\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\"]}', '{\"description\":\"1、导出EXCEL表后才能转TXT文本\\n2、导出EXCEL表的分页行数需要注意\\n不能超过原表格的最大行数（如20），否则会超出行数乱码\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\"]}', NULL, 0, 1, '2026-02-28 13:36:06', '2026-02-28 14:56:08');
INSERT INTO `feature_document` VALUES (5, '快速涂色赋注解', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「快速改色/赋注解工具」可用于建模档批量改孔颜色、分析修改注释。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/92794b2be10e40f5802e18ce5a321b01.png\"]}', '[{\"title\":\"建模档出图标准设置\",\"description\":\"建模档出图标准设置\\n在进行上色之前要先选择设计标准，这以启泰为例，若没有设置出图标准则会弹出以下信息。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/d5c16829b576405b9043b29436aef6d8.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/e5ca78a1213948e4be152eb58d0cdec3.png\"]},{\"title\":\"特征注解\",\"description\":\"1、选择“特征注解表”； \\n2、单击“打开配置表” -> 对特征等参数进行配置。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/34a30fe26c434856809cdde2368eae24.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f56c5bd691fc40118cd419dedd842d49.png\"]},{\"title\":\"材质颜色\",\"description\":\"1、选择“材质颜色表”； \\n2、单击“打开配置表” -> 对材质颜色等参数进行配置。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/01401fbeda5e4a59918d00bb40de8c60.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ec2f901f3e8f436a811b9957d6492ce0.png\"]},{\"title\":\"工件分析\",\"description\":\"1、打开快速改色/赋注解工具，框选工件分析；\\n2、分析之后选择对应工件，可在下方列表检查修改注释；\\n3、双击对应注释(也可单选)，单独显示工件同时高亮孔，选上方图片，推荐孔修改；\\n4、修改孔颜色并赋予注解；\\n5、可选择公制、英制、美制，大板是否注解槽等；\\n6、分析检查孔色，没有识别出特征（包括颜色是否涂对、配置表有该种材质及配色）的孔为抄底注释。\\n7、手动添加注解，选面添加对应模板注释。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c98d5290df214cd5a539e518cb9d7941.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6ac10997e814455bba9c79bbace26924.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7c226ea15a22459ca69bbad1f5c0f98c.png\"]},{\"title\":\"查看标准件\",\"description\":\"1、使用过程中，可点图层开关进行查看标准件，不会影响程序。\\n2、同理，右方涂色工具可同时使用，不会影响程序。\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/3426c598add7462ba87b3ad7c864e6bb.png\"]},{\"title\":\"选择涂色\",\"description\":\"1、勾选 “选择涂色”，手动选择面和体进行颜色修改；\\n2、勾选需要更改颜色的面和体所在的图层；\\n3、在 “加工颜色（面色）” 里选择材质颜色 -> 弹出“选择面”对话框 -> 选择需要上色的面，除“任意色”外其他颜色都不能直接更改色号，需要通过配置表更改色号；\\n4、在 “材质颜色（体色）” 里选择材质颜色 -> 弹出“选择实体”对话框 -> 选择需要上色的体，除“任意色”外其他颜色都不能直接更改色号，需要通过配置表更改色号。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f364cf96dde343bda6f455bd6f253026.png\"]}]', '{\"description\":\"步骤一：选择设计标准\\n根据客户选择设计标准。\\n步骤二：选体分析\\n设置大板是否注解槽，框选多个实体进行分析注释。\\n步骤三：上色\\n根据材质推荐色给孔上色。\\n步骤四：修改、添加注解\\n          选面添加注解，点击注释在文本框修改内容。\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\"]}', '{\"description\":\"在UI功能手动修改、添加注释时按回车即可\",\"images\":[]}', NULL, 0, 1, '2026-02-28 13:44:01', '2026-02-28 15:00:12');
INSERT INTO `feature_document` VALUES (6, '建模档合并订料', '', '范田田', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「建模档合并订料」可用于建模档订料的合并，你可在「建模档合并订料」完成建模档合并订料操作。\\n注意：备料前，工件需要排序赋予属性；备料后，备料板需要排序和赋属性。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6d9d91dd61894186948cea8cb0482ed6.png\"]}', '[{\"title\":\"小板过滤\",\"description\":\"1.小板过滤\\n1.1 单击“小板过滤”按钮，弹出“备料零件过滤” UI对话框； \\n1.2 过滤条件：按大小或者按重量进行过滤，填写过滤条件； \\n1.3 过滤对象：隐藏或者显示 符合条件的对象；\\u000B\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c36bb166b5b44946820f07fbd8b6b4ed.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/782722c5a1a3413394ac1280955f2ba2.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8459d548b3a24dbc8bf331f3a51b7912.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2c13910d50fa435385a3e1e30fcb8050.png\"]},{\"title\":\"增加实体\",\"description\":\"2.增加实体\\n          途径一：\\n2.1 单击“增加实体”按钮，弹出“选择实体” UI对话框；\\n2.2 选择需要备料的对象，注意已备料的实体无法选中；\\n2.3 指定放置点；\\n2.4 设置备料的列数，这里设置了7列。\\n注意：如果“增加实体”无法选中，先“指定放置点”\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/98007e99dda944f1b39c06d873a7e370.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/be736276aaac4e43b46257192563a41e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7e1e8559635d48579535a948c706a522.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/bc6f1237ec924deaaa2d515b5183671a.png\"]},{\"title\":\"增加实体\",\"description\":\"2.增加实体\\n途径二：\\n2.5 单击“编辑备料板”按钮；\\n2.6 弹出“选择实体” UI对话框，选中需要编辑的备料板；\\n2.7 单击“增加实体”按钮；\\n2.8 弹出“选择实体”UI对话框，选中需要增加的实体；\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/d0a74d87b2db4a51843bbf95cdf1a01c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de5db7f4b9c49328e06745f285067ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/eb59315ac76445b3bd28f2849687d9a0.png\"]},{\"title\":\"删除实体\",\"description\":\"3.删除实体\\n3.1 单击“删除实体”，弹出“选择需要移除的实体” UI对话框；\\n3.2 选择删除的对象。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\"]},{\"title\":\"零件分版\",\"description\":\"4.零件分版\\n4.1 单击“零件分版”按钮，弹出“选择实体” UI对话框；\\n4.2 选择需要另外分版的对象；\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b375f47101d549a888ce8f24e69cfde3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/35db06d98dcd49d8856a2922f06692d4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f96c50dcf32e46b3a2c290a762f638d4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/56868feb14bd4d208c17a22af852bc89.png\"]},{\"title\":\"自动摆正工件\",\"description\":\"5.自动摆正工件\\n5.1 单击“编辑备料版”按钮，弹出“选择实体”对话框，可以输入名称查找，也可以直接单击选择需要编辑的备料版（推荐）；\\n5.2 单击“自动摆正工件”，备料版内的工件重新自动排版；\\n5.3 设置备料的列数，这里设置了4列。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b023be516c948b2809a79e648531d7e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f5a79c72d0b1408682a1f6bb7cf48c30.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/179fc1382de94c8fb1f5a78c3d6ad75c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/a0e790c4b8d34a448dbd471f91bfe062.png\"]},{\"title\":\"旋转和翻转\",\"description\":\"6.左旋90度\\n6.1 单击“左旋90度”按钮，弹出“选择对象” UI对话框；\\n6.2 选择需要左旋90度的对象；\\n7.右旋90度\\n6.1 单击“右旋90度”按钮，弹出“选择对象” UI对话框；\\n6.2 选择需要右旋90度的对象；\\n8.左右翻转\\n6.1 单击“左右翻转”按钮，弹出“选择对象” UI对话框；\\n6.2 选择需要左右翻转的对象；\\n9.上下翻转\\n6.1 单击“上下翻转”按钮，弹出“选择对象” UI对话框；\\n6.2 选择需要上下翻转的对象；\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\"]},{\"title\":\"动态调整位置\",\"description\":\"10.动态调整位置\\n10.1 单击“动态调整位置”按钮，弹出“重定位” UI对话框；\\n10.2 选择需要动态调整位置的对象（可以多选），指定方位；\\n10.3 “仅移动手柄” ：\\n手柄位置默认在选中所有工件的中心点，通过改变手柄的位置来改变选中工件的旋转中心。\\n（1）勾选上可以改变手柄位置，工件不做调整；\\n（2）取消勾选，工件会随手柄动态调整；\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\"]},{\"title\":\"依WCS摆正工件\",\"description\":\"11.依WCS摆正工件\\n① 工件坐标系到绝对坐标系摆正定位，可用于两个角度以上较难摆正的工件；\\n② 选择需要摆正的体，选择体的顶面，指定CSYS设置工件坐标；\\n③ 点击对话框，手动对齐工件与CSYS的坐标；\\n④ 动态对齐，X轴对齐工件直边，确定即可。\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f19fc277e1f944ae9d44897308ca3133.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/afa8888118ce42fa9ff20081e09e6bfb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ae7ff1c437ac49aea3e05b88aebda394.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/422c03f1a6464dec9f9d53a56d48cc5f.png\"]},{\"title\":\"对齐\",\"description\":\"12.对齐\\n12.1 单击“对齐”按钮；\\n12.2 弹出对话框，可以输入名称查找，也可以直接单击选择面。以第一个选择的面为参考面，后面选择的面都和第一个面对齐；\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7377460e0fa04685a1b56234a6adff87.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d9d7036787194079b778d8fc341b6ff5.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9669bfaf1fae4eda89d745539521f142.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f36a4f65ef034bbeb6a1e30e231c85e2.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\"]},{\"title\":\"外形尺寸\",\"description\":\"13.外形尺寸\\n勾选“外形尺寸”后，可以对备料板的长、宽、高预值进行估算。\\n当长、宽、高为 0 时，表示不限值。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/955ae6e4a50a4c9c84347cccbad72a56.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f4359069e53d423884ab0d9d132d3857.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4c6c76944a8643928d8a6ecbe5b8273e.png\"]},{\"title\":\"重量\",\"description\":\"14.重量\\n勾选“重量”后，可以对备料板的重量预值进行估算，当超出备料板的实际重量超出预值，便会弹出消息提示框 “备料板重量超出限定值” 。\\n当重量为  0 时，表示不限值。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\"]},{\"title\":\"厚度容差\",\"description\":\"15.厚度容差\\n① 厚度超过设置的数值后，程序会自动分开不同高度的工件\\n例如：厚度容差设置为1，则高度为60和62的工件会分开备料，\\n设置为10，则高度60和62的工件不会分开备料。\\n② 默认值为零时，不做限制\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/94437365c26c4283b7b3a2671eab2e3f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7f91ebd4692a4cb2aa3a7ab2b0a10017.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f68971d517584b74b26a13b7b7f56700.png\"]},{\"title\":\"备料数量\",\"description\":\"16.备料数量\\n① 定义备料板的数量，默认值为1\\n当选择16件相同的工件进行备料，全部在一个备料板会超过机器的最大加工行程，就可以分成2个备料板进行备料，此时备料数量为2，每个备料板有6个工件；\\n如果分成2个备料板还是超出了最大加工形成，就可以分成4个备料板进行备料，此时备料数量为4，每个备料板有4个工件；\\n② 注意在3D图档内没有生成对应实体，在BOM表数量处可体现。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6462c17efc1f4bca83b99d9823e4e0b2.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4dcce90227284d0d98516722546ea2d2.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/06c39edd671e410c9b426e30371402fe.png\"]},{\"title\":\"上对齐\",\"description\":\"17.上对齐\\n勾选上对齐后，会对备料板内的工件进行上表面对齐操作。\\n用于工件的顶面对齐，默认情况下备料板都是以底面对齐，保证见光度\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f5c36723957847558b130bdf1fc205f6.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1df353d47f0b49209723a89a4e7f4b27.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/19399ac20b0b4ff8a7d9055cd6e511a0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/163ed48172064b8bbe119ae4c59b555e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/c620825cbd124b0b899fed0a1ce3adef.png\"]},{\"title\":\"隐藏已备料\",\"description\":\"18.隐藏已备料\\n勾选上“隐藏已备料”，可以对已备料的工件进行隐藏；\\n若不勾选，则备料了的工件还会存在于原位置。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b57768b917614aa486ecb1619b879ff5.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3e76e2ce4981482ca8fefdf555ad11d4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/47564bebde9b420ba527bc6432dfc28e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2c67ad571b0c415c81b9aa6aca4e9322.png\"]},{\"title\":\"前距、后距、左距、右距\",\"description\":\"19、前距、后距、左距、右距\\n备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\"]},{\"title\":\"行距、列距\",\"description\":\"20. 行距、列距\\n备料板尺寸的大小会随行距、列距的值变化而变化。\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/d208a6da4ef246b79ed75e3ca03a8b8c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2d89d4c53de44090ae14c18c31c3019d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\"]},{\"title\":\"上距、下距\",\"description\":\"20. 上距、下距\\n备料板尺寸的大小会随上距、下距的值变化而变化。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4733348413e4496dad66233b69210d6c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/39f525717b234f00a3f641e4cbfec717.png\"]}]', '{\"description\":\"步骤一：小板过滤  \\n过滤出指定大小、重量的工件。\\n步骤二：对工件进行备料  \\n对备料板内的工件进行增加、删除、零件分板操作。\\n步骤三：调整工件位置 \\n通过左旋90度、右旋90度、左右翻转、上下翻转、动态调整位置、依WCS摆正工件、对齐、自动摆正工件来调整工件位置。\\n步骤四：调整工件间距\\n通过调整示意图内的前距、后距、左距、右距、上距、下距、行距、列距来调整工件之间的间距。\\n步骤五：预设值 \\n通过预设尺寸、重量、厚度容差来判断备料板是否超过机器的最大加工行程。\\n步骤六：备料板数量 \\n对超出机器的最大加工行程的备料板进行多次备料，设置需要的备料板数量。 \\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\"]}', '{\"description\":\"1.不同图层工件不能在一起备料\\n2.备料完之后需要给备料板排序和赋属性，否则不会出图\\n\",\"images\":[]}', NULL, 0, 1, '2026-02-28 14:18:10', '2026-02-28 15:20:15');
INSERT INTO `feature_document` VALUES (7, '零件刻字', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「零件刻字工具」可用于建模档排序赋属性后的带属性刻字。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\"]}', '[{\"title\":\"零件刻字\",\"description\":\"1 刻字类型\\n非标件刻字和标准价刻字；\\n2 文本放置位置\\n平面刻字和圆柱面刻字；\\n3 刻字方式\\n分割面刻字、凹槽刻字和凸起刻字；\\n4 选择刻字属性\\n4.1 在前缀\\\\模号内可自定义输入内容；\\n4.2 勾选编号、材质、热处理会识别所选体的编号、材质、热处理属性；\\n4.3 刻字颜色可自定义；\\n4.4 刻字内容可自定义输入；\\n4.5 更新显示可更新刻字内容，也可通过回车来实现更新效果；\\n5 调整文本尺寸和位置\\n字高、字宽及宽高比可自定义设置值，指定方位只能旋转面平行方向和四方移动。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\"]}]', '{\"description\":\"步骤一   刻字类型\\n选择非标件刻字或标准价刻字；\\n步骤二   文本放置位置\\n选择平面或圆柱面，选择平面的左半边，刻字会正放置，选择平面的右半边，刻字会反放置；\\n步骤三   刻字方式\\n选择分割面刻字、凹槽刻字或凸起刻字；\\n步骤四   选择刻字属性\\n1 、在前缀\\\\模号自定义输入刻字内容；\\n2、 选择勾选编号、材质、热处理；\\n3、 自定义刻字颜色；\\n4 、自定义输入刻字内容；\\n5 、更新显示或回车；\\n步骤五   调整文本尺寸和位置\\n自定义字高、字宽及宽高比，调整文本位置。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\"]}', '{\"description\":\"1、圆柱面会挖一个平面做刻字；\\n2、选择平面的左半边，刻字会正放置，选择平面的右半边，刻字会反放置。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b4147a68c72e44a6804b3eeb03b8072b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/969aa85fa38b47d8b7ceb9386570b453.png\"]}', NULL, 0, 1, '2026-02-28 14:20:17', '2026-02-28 15:24:17');
INSERT INTO `feature_document` VALUES (8, '快速涂色', '', '范田田', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「快速改色工具」可用于建模档体、孔、键槽、面的批量切换颜色。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\"]}', '[{\"title\":\"建模档出图标准设置\",\"description\":\"1、建模档出图标准设置\\n在进行上色之前要先选择设计标准，这以启泰为例，若没有设置出图标准则会弹出以下信息。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/674b98cdf2cf4926a315685cabfc1946.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\"]},{\"title\":\"特征等参数配置\",\"description\":\"1、选择“特征注解表”； \\n2、单击“打开配置表” -> 对特征等参数进行配置。\\n\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\"]},{\"title\":\"颜色参数配置\",\"description\":\"1、选择“材质颜色表”； \\n2、单击“打开配置表” -> 对材质颜色等参数进行配置。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\"]},{\"title\":\"体色\",\"description\":\"1、选择“体色”，对体进行颜色修改；\\n2、勾选需要更改颜色的体所在的图层；\\n3、“选择体”，过滤器会过滤实体，只能选实体；\\n4、选择需要上色（改色）的材质，在“选择的材质”查看当前的配置色；没有识别出特征（包括颜色是否涂对、配置表有该种材质及配色）的体为红色字体；识别出了特征的体为绿色字体；配置好了特征但是还没有完成上色的体为橙色字体；配置好了特征且已经上色的孔为蓝色字体；\\n5、给选择的材质配置颜色，可以全部配置好了后再 “一键涂色” ；\\n6、若勾选“隐藏体”，“一键涂色”后会将 “选择的体” 进行隐藏；\\n7、色号配置好了后，要点击“一键涂色”，相当于“应用”、“确定”；\\n8、已经完成上色的体，Y/N = Y；没有完成上色的体，Y/N =N。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7179f4f725e947338d00ba51aa0f5e6d.png\"]},{\"title\":\"孔色\",\"description\":\"1、选择“孔色”，对孔进行颜色修改；\\n2、勾选需要更改颜色的孔所在的图层；\\n3、“选择孔”，过滤器会过滤圆柱面，只能选择面；\\n4、一键清空选择的孔；\\n5、选择公制、英制、美制，进行孔筛选；\\n6、分析检查孔色，没有识别出特征（包括颜色是否涂对、配置表有该种材质及配色）的孔为红色字体；识别出了特征的孔为绿色字体；配置好了特征但是还没有上色的孔为橙色字体；配置好了特征且已经上色的孔为蓝色字体；\\n7、根据孔的特征推荐孔色号；\\n8、色号配置好了后，要点击“一键涂色”，相当于“应用”、“确定”；\\n9、已经完成上色的孔，Y/N = Y；没有完成上色的孔，Y/N = N 。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/952ab9fca56045968f31fc94e364992b.png\"]},{\"title\":\"键槽\",\"description\":\"1、选择 “键槽”，对板内的键槽进行颜色修改；\\n2、勾选需要更改颜色的键槽所在的图层；\\n3、在 “快速改键槽色” 里选择键槽类型 -> “选择有键槽的板” -> “选择键槽底面”；\\n4、单击 “一键涂色”，相当于“应用”、“确定”。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/e0c065e99bf2472681128c68130ca87e.png\"]},{\"title\":\"选择涂色\",\"description\":\"1、勾选 “选择涂色”，手动选择面和体进行颜色修改；\\n2、勾选需要更改颜色的面和体所在的图层；\\n3、在 “加工颜色（面色）” 里选择材质颜色 -> 弹出“选择面”对话框 -> 选择需要上色的面，除“任意色”外其他颜色都不能直接更改色号，需要通过配置表更改色号；\\n4、在 “材质颜色（体色）” 里选择材质颜色 -> 弹出“选择实体”对话框 -> 选择需要上色的体，除“任意色”外其他颜色都不能直接更改色号，需要通过配置表更改色号。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\"]}]', '{\"description\":\"步骤一：选择设计标准\\n根据品牌选择设计标准。\\n步骤二：检查配置表\\n根据品牌检查特征注解表和材质颜色表，对不符合需求的参数进行修改。\\n步骤三：筛选材质\\n对选择的体、孔、键槽、面进行图层、材质类型、材质颜色过滤。\\n步骤四：上色\\n根据材质推荐色给材质上色。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/592884368b0a4291b03fa137a9bd99c8.png\"]}', '{\"description\":\"快速涂色找不到配置表\\n在进行上色之前要先选择设计标准，这以启泰为例，若没有设置出图标准则会弹出以下信息。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\"]}', NULL, 0, 1, '2026-02-28 14:28:53', '2026-03-01 08:57:18');
INSERT INTO `feature_document` VALUES (9, '出图预设', '', '黄坤华', '1.0', '2026-02-28', 'keytime', '{\"description\":\"智一「建模档出图预设」\\n设置出图标准与公共信息填写，例客户、模号；可用于公共信息自动关联出图、导BOM\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\"]}', '[{\"title\":\"公共信息预设\",\"description\":\"1、选择用户标准\\n2、填写公共信息（可在基本属性配置表配置需要填写的公共信息）\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6b6bba4a459883c88177a901022f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\"]}]', '{\"description\":\"步骤一:选择用户标准\\n步骤二:填写公共信息\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\"]}', '{\"description\":\"快速涂色报错\\n在进行上色之前要先选择设计标准，这以启泰为例，若没有设置出图标准则会弹出以下信息。\\n\",\"images\":[\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/135f645e3ef54410b6167b39d47db15b.png\"]}', NULL, 0, 1, '2026-02-28 14:31:09', '2026-03-01 08:32:41');

SET FOREIGN_KEY_CHECKS = 1;
